type ListPeriodsParams struct {
	TenantID   int64
	PropertyID int64
}

type ListPeriodsRow struct {
	PeriodStart  civil.Date
	Status       string
	ClosedAt     *time.Time
	ClosedBy     *int64
	ReopenedAt   *time.Time
	ReopenedBy   *int64
	ReopenReason *string
}

// ---------------------------------------------------------------------------------------------------------------
// Periods (calendar months)
func (q *Queries) ListPeriods(ctx context.Context, arg ListPeriodsParams) ([]ListPeriodsRow, error) {
	rows, err := q.db.Query(ctx, listPeriods, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPeriodsRow{}
	for rows.Next() {
		var i ListPeriodsRow
		if err := rows.Scan(
			&i.PeriodStart,
			&i.Status,
			&i.ClosedAt,
			&i.ClosedBy,
			&i.ReopenedAt,
			&i.ReopenedBy,
			&i.ReopenReason,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

